#!/bin/sh
# AgentGuard for Codex: hook launcher. GENERATED by agentguard.adapters.codex.plugin -- do not edit.
#
# Codex runs every AgentGuard hook as:  /bin/sh "${PLUGIN_ROOT}/hooks/agentguard-hook.sh" <event>
# with the hook payload on stdin. This script only finds the AgentGuard runtime and hands the
# payload to it; all logic lives in the runtime, so upgrading AgentGuard never changes this
# plugin (Codex makes you re-trust a plugin's hooks whenever any of its files change).
#
# Lookup order: $AGENTGUARD_CODEX_HOOK, then `agentguard-codex-hook` on PATH, then a private copy in
# Codex's per-plugin data directory ($PLUGIN_DATA), which the session-start hook installs
# with uv on first use (set AGENTGUARD_NO_BOOTSTRAP=1 to prevent that).
#
# It always exits 0. Codex reads exit code 2 as "block this", and a launcher problem must
# never block the developer's work.

event="${1:-}"
case "${AGENTGUARD_DISABLE:-}" in 1|true|TRUE|True|yes|on) exit 0 ;; esac

runtime_source="${AGENTGUARD_SOURCE:-git+https://github.com/tohin003/AgentGuard}"
private="${PLUGIN_DATA:-}/runtime"
runner=""
if [ -n "${AGENTGUARD_CODEX_HOOK:-}" ] && [ -x "$AGENTGUARD_CODEX_HOOK" ]; then
  runner="$AGENTGUARD_CODEX_HOOK"
elif command -v agentguard-codex-hook >/dev/null 2>&1; then
  runner="agentguard-codex-hook"
elif [ -n "${PLUGIN_DATA:-}" ] && [ -x "$private/bin/agentguard-codex-hook" ]; then
  runner="$private/bin/agentguard-codex-hook"
fi

if [ "$event" = "session-start" ] && [ -n "${PLUGIN_DATA:-}" ] && [ -z "${AGENTGUARD_NO_BOOTSTRAP:-}" ] \
  && [ "$runner" = "$private/bin/agentguard-codex-hook" -o -z "$runner" ] \
  && [ "$(cat "$private/source" 2>/dev/null)" != "$runtime_source" ] && command -v uv >/dev/null 2>&1; then
  # Install (or re-install, when the source changed) a private runtime. Never onto PATH,
  # never inside the plugin root. Output goes to a log, not to Codex.
  mkdir -p "$private" 2>/dev/null
  if UV_TOOL_DIR="$private/tools" UV_TOOL_BIN_DIR="$private/bin" \
    uv tool install --quiet --reinstall "$runtime_source" </dev/null >>"$private/install.log" 2>&1; then
    printf '%s' "$runtime_source" >"$private/source"
  fi
  [ -x "$private/bin/agentguard-codex-hook" ] && runner="$private/bin/agentguard-codex-hook"
fi

if [ -z "$runner" ]; then
  if [ "$event" = "session-start" ]; then
    printf '%s\n' '{"systemMessage": "AgentGuard is installed as a Codex plugin, but its runtime was not found, so this session is UNGUARDED. Install it with: uv tool install git+https://github.com/tohin003/AgentGuard  (or put agentguard-codex-hook on PATH), then start a new session."}'
  fi
  exit 0
fi

"$runner" "$event"
exit 0
